script:
frappe.ui.form.on('Tenant', {
    refresh(frm) {
        const call = (method) => {
            return frappe.call({
                method: 'songa_multi_tenancy.api.v1.tenants.' + method,
                args: { tenant: frm.doc.name },
            }).then(() => frm.reload_doc());
        };

        const confirm_call = (label, method) => {
            frappe.confirm(label, () => call(method));
        };

        if (frm.doc.status === 'Active') {
            frm.add_custom_button(__('Suspend'), () => {
                confirm_call(
                    __('Suspend this tenant? Its users will lose access until reactivated.'),
                    'suspend_tenant'
                );
            }, __('Actions'));

            frm.add_custom_button(__('Pause'), () => {
                confirm_call(
                    __('Pause this tenant? Its users will lose access until reactivated.'),
                    'pause_tenant'
                );
            }, __('Actions'));
        }

        if (['Suspended', 'Paused', 'Pending', 'Archived', 'Deleted'].includes(frm.doc.status)) {
            frm.add_custom_button(__('Activate'), () => {
                call('activate_tenant');
            }, __('Actions'));
        }

        if (!['Archived', 'Deleted'].includes(frm.doc.status)) {
            frm.add_custom_button(__('Archive'), () => {
                confirm_call(
                    __('Archive this tenant? Its users will lose access.'),
                    'archive_tenant'
                );
            }, __('Actions'));
        }

        if (frm.doc.status !== 'Deleted') {
            frm.add_custom_button(__('Delete Tenant'), () => {
                frappe.confirm(
                    __('Mark this tenant as deleted? Its users will be disabled and unable to log in. Data is preserved.'),
                    () => call('delete_tenant')
                );
            }, __('Actions'));
        }
    }
});
